import { AppContext } from "approot/global/services/context";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { AlertsService } from "approot/global/providers/uikit.alerts";
import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";
import SearchSource from "approot/global/searchSource";
import { UnderscoreStatic } from "underscore";
import { ParentPayRepository } from "../../parentpay.repository";
import { NamedEntityDto } from "approot/global/models/common.model";

declare var _: UnderscoreStatic;
declare var extDeferred: any;

export class SetSchoolLinkController extends NetCityModalController {
	public header: string;
	public school: NamedEntityDto;
	public search: SearchSource;
	public searchSettings: any;

	/*@ngInject*/
	constructor(
		$http: any,
		$scope: any,
		public $dialogs: DialogsService,
		private $alerts: AlertsService,
		public language: any,
		appContext: AppContext,
		public $uibModalInstance,
		changeTracker,
		private payments: any,
		private parentPayRepository: ParentPayRepository,
		private $q
	) {
		super($scope, $uibModalInstance, changeTracker, $dialogs);
		let searchSettings = {
			schools: {
				url: "/webapi/schools/search",
				params: {
					searchParam: "name",
					take: 100
				}
			}
		};
		this.header = "Привязка ОО";
		this.search = new SearchSource(searchSettings, $http);
	}

	saveProcess(): void {
		$(document).trigger("showProcessing");
		this.parentPayRepository.setSchoolLink(this.school.id, this.payments.map(x => x.id)).then(() => {
			this.$uibModalInstance.close();
			this.$alerts.success(this.language.Generic.Common.kDataSaved);
		});
	}

	save(): void {
		var notValidMessage = this.notValid();
		if (notValidMessage) {
			this.$dialogs.message(notValidMessage);
		} else {
			$(document).trigger("showProcessing");
			var confirms = [];
			var confirmFunc = (confirmMessages) => {
				if (confirmMessages && confirmMessages.length) {
					confirmMessages.forEach(confirmMessage =>
						confirms.push(() => this.$dialogs.confirm(confirmMessage)));
				}
			}
			this.$q.all([
				this.confirmCheckSchoolLink().then(confirmFunc),
				this.confirmDifferentPayOrgs().then(confirmFunc)
			]).then(() => {
				$(document).trigger("closeProcessing");
				if (confirms.length) {
					extDeferred.when(confirms).then(() => {
						this.saveProcess();
					});
				} else {
					this.saveProcess();
				}
			});
		}

	}

	notValid(): string {
		if (!this.payments) {
			return "Пустой список платежей";
		}
		if (!this.school) {
			return "Выберите ОО";
		}
		return "";
	}

	confirmDifferentPayOrgs(): Promise<string[]> {
		return new Promise((resolve) => {
			if (_.keys(_.groupBy(this.payments, "payOrg")).length > 1) {
				resolve(["Внимание! Значения поля \"Организация в платеже\" у выбранных платежей различаются.\nВы желаете продолжить?"]);
			};
			resolve([]);
		});
	}

	confirmCheckSchoolLink(): Promise<string[]> {
		return this.parentPayRepository.getSchoolLinks(this.payments.map(x => x.id)).then(
			(links) => {
				if (!links) {
					return [];
				}
				var errorLinks = links.filter(link => { return link.school != null });
				if (!errorLinks.length) {
					return [];
				}
				var result = errorLinks.map((link) => `Выбранный платеж уже привязан с ОО ${link.school.name}.\nВ случае продолжения платеж будет привязан с ${this.school.name}.\n${link.payDate}, ${link.payNumber}, ${link.payInfo}\nВы желаете продолжить?`);
				return result;
			});
	}
}

export const SetSchoolLinkComponent = {
	controller: SetSchoolLinkController,
	templateUrl: "/static/dist/app/em/parentpay/payrecords/registry/setSchoolLink.component.html"
}



