import { BaseRepository } from "approot/global/repository.js";
import { NamedEntityDto } from "approot/global/models/common.model";

export class ParentPayRepository extends BaseRepository {
	setSchoolLink(schoolId: number, paymentIds: number[]) {
		return this.$http.post("/webapi/em/parentpay/payrecords/schools", paymentIds, { params: { schoolId: schoolId } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	clearSchoolLink(paymentId: number) {
		return this.$http.delete("/webapi/em/parentpay/payrecords/schools", { params: { paymentId: paymentId } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getSchoolLinks(paymentIds: number[]) {
		return this.$http.get("/webapi/em/parentpay/payrecords/getSchoolLinks", { params: { paymentIds: paymentIds } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}
}




