"use strict";

import { CommonXhrErrorHandler } from "webroot/static/src/common/js/common.error.js";

let staticInstance = null;

export class BaseRepository {
	constructor($http, $dialogs, $alerts) {
		this.$http = $http;
		this.$dialogs = $dialogs;
		this.$alerts = $alerts;
		staticInstance = this;
	}

	handleResponse(response) {
		$(document).trigger("closeProcessing");
		return response.data;
	}

	handleError(response) {
		const errInformer = (message) => staticInstance.$dialogs.error(message);
		const messageInformer = (message) => staticInstance.$dialogs.message(message);
		return new CommonXhrErrorHandler(errInformer, messageInformer).handleErrorResponse(response);
	}
}
BaseRepository.$inject = ["$http", "$dialogs", "$alerts"];



