declare var angular: any;

const module = angular.module("irtech.netcity.em.parentpay",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
		"irtech.netcity.common", "irtech.netcity.ui-components"
	]);

const registryTemplate = "/static/dist/app/global/templates/registryAs.html";

import { ParentpayRegistryController } from "./payrecords/registry/parentpayRegistry.component";
import { SetSchoolLinkController } from "./payrecords/registry/setSchoolLink.component";
import { ParentPayRepository } from "./parentpay.repository";

module
	.service("parentPayRepository", ParentPayRepository)
	.controller("ParentpayRegistryController", ParentpayRegistryController)
	.controller("SetSchoolLinkCtrl", SetSchoolLinkController)
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/payrecords/registry/", {
				templateUrl: registryTemplate,
				controller: "ParentpayRegistryController as ctrl"
			})
			.otherwise({
				templateUrl: registryTemplate,
				controller: "ParentpayRegistryController as ctrl"
			});
		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



