import { RegistryController, RegistryInfo, RegistryBtn, SelectionMode, Decorator } from "approot/global/controllers/registryAsCtrl";
import { PageContext, AppContext } from "approot/global/services/context";
import { DialogsService, IFileDialogOptions } from "approot/global/providers/uikit.dialogs";
import { AlertsService } from "approot/global/providers/uikit.alerts";
import { ParentPayRepository } from "../../parentpay.repository";
import { AppLoader } from "approot/global/apploader";
import { SetSchoolLinkComponent } from "./setSchoolLink.component";
import { EnqueueInfo } from "approot/global/services/queue/taskqueue.model";
import { TaskQueueService } from "approot/global/services/queue/taskqueue.service";

export class ParentpayRegistryController extends RegistryController {
	private parentPayRepository: ParentPayRepository;
	private taskQueueService: TaskQueueService;
	/*@ngInject*/
	constructor(
		pageContext: PageContext,
		$injector: any,
		$scope: ng.IScope,
		$appLoader: AppLoader,
		$dialogs: DialogsService,
		$uibModal: ng.ui.bootstrap.IModalService,
		$alerts: AlertsService,
		language: any,
		appContext: AppContext,
		parentPayRepository: ParentPayRepository,
		taskQueueService: TaskQueueService
	) {

		pageContext.title = language.Generic.MenuFolders.kParentPayPayments;
		pageContext.parent = null;

		const importButton: RegistryBtn = {
			title: language.Generic.Buttons.kImport,
			action: () => this.import(),
			icon: "glyphicon glyphicon-import",
		};

		const setSchoolLinkButton: RegistryBtn = {
			title: "Указать ОО",
			icon: "glyphicon glyphicon-link",
			selectionMode: SelectionMode.Multiple,
			action: () => {
				this.setSchoolLink();
			}
		};

		const clearSchoolLinkButton: RegistryBtn = {
			title: "Удалить привязку ОО",
			icon: "glyphicon glyphicon-remove",
			selectionMode: SelectionMode.Single,
			action: () => {
				this.clearSchoolLink();
			}
		};

		const registry: RegistryInfo = {
			url: "/webapi/em/parentpay/payrecords/registry",
			filtersUrl: "/webapi/em/parentpay/payrecords/registry/filter",
			linkButtons: appContext.isTopEm ? [ importButton ] : [],
			fieldDecorators: {
				pay: new CurrencyDecorator()
			},
			buttons: [setSchoolLinkButton, clearSchoolLinkButton],
			extensions: null,
			compactFilters: true
		};

		super($injector, $scope, $appLoader, $dialogs, $uibModal, $alerts, language, registry);
		this.parentPayRepository = parentPayRepository;
		this.taskQueueService = taskQueueService;
	}

	clearSchoolLink() {
		let selected = this.selection.selected;
		this.$dialogs.confirm("Удалить привязку ОО?").then(() => {
			this.parentPayRepository.clearSchoolLink(selected[0].id).then(() => {
				this.$alerts.success(this.language.Generic.Common.kDataSaved);
				this.load();
			});
		});
	}

	setSchoolLink() {
		let selected = this.selection.selected;
		const modalInstance = this.$uibModal.open({
			templateUrl: SetSchoolLinkComponent.templateUrl,
			controller: SetSchoolLinkComponent.controller,
			controllerAs: "$ctrl",
			size: "lg",
			resolve: {
				payments: () => selected
			}
		});

		modalInstance.result.then(() => {
			this.load();
		});
	}

	import() {
		let options: IFileDialogOptions = {
			url: "/webapi/em/parentpay/payrecords/registry/import",
			fileExts: [".xls", ".xlsx"],
		}

		this.$dialogs.uploadFile<EnqueueInfo>("Импорт платежей", options)
			.then((uploadResult) => {
				let enqueueInfo = uploadResult.result;

				let taskOptions = { getTaskFunc: () => Promise.resolve(enqueueInfo) };
				return this.taskQueueService.execute<ImportPayRecordsResult>(taskOptions);
			})
			.then((result) => {
				if (result) {
					let message = "";
					if (result.message) {
						message += result.message + "\n";
					}
					message += `Всего обработано записей: ${result.recordsProcessed}.\n`;
					message += `Импортировано новых записей: ${result.recordsImported}.\n`;
					message += `Кол-во записей, для которых были определены требуемые атрибуты (номер лиц. счета и/или ФИО воспитанника): ${result.parsedRecords}.\n`;
					if (result.unRecognizedOrgs > 0) {
						message += `Кол-во записей, для которых не удалось определить организацию: ${result.unRecognizedOrgs}.\n`
					}
					if (result.unRecognizedStudents > 0) {
						message += `Кол-во записей, для которых не удалось определить воспитанника: ${result.unRecognizedStudents}.\n`;
					}
					message += `Сформировано связей платежей с воспитанниками: ${result.newStudentLinks}.\n`;

					if (result.success) {
						this.$dialogs.message(message, "Успешный импорт").then(() => this.load());
					} else {
						this.$dialogs.error(message, "Ошибка при импорте");
					};
				}
			});
	}
}

//todo. выделить в пространство global
export class CurrencyDecorator implements Decorator {
	private format(value: number, minorLength: number, partsDelimeter: string = " ", digitsParts: number = 3): string {
		var re = '\\d(?=(\\d{' + (digitsParts || 3) + '})+' + (minorLength > 0 ? '\\.' : '$') + ')';

		return value.toFixed(Math.max(0, ~~minorLength)).replace(new RegExp(re, 'g'), '$&' + partsDelimeter);
	}

	public activate(scope: ng.IScope, element: any) {
		let value = parseInt(scope["content"]);
		let formatted = this.format(value, 2);
		scope["content"] = formatted + " р.	";
		element.css("white-space", "pre")
	}
}

class ImportPayRecordsResult {
	public recordsProcessed: number; // Кол-во обработанных строк
	public newStudentLinks: number; // Кол-во новых привязок с воспитанниками
	public recordsImported: number; // Кол-во импортированных записей
	public parsedRecords: number; // Кол-во записей, для которых были определены требуемые атрибуты (номер лиц. счета и/или ФИО учащегося)
	public unRecognizedOrgs: number; // Кол-во записей, для которых не удалось определить организацию
	public unRecognizedStudents: number; // Кол-во записей, для которых не удалось определить учащегося
	public success: boolean; // Признак успешности импорта
	public message: string; // Сопровождающее сообщение
}

export const ParentPayRegistryComponent = {
	controller: ParentpayRegistryController
}


